    {
      "name": "Finset.sum_update_of_mem",
      "type": " {ι : Type u_1} {M : Type u_2} [AddCommMonoid M] [DecidableEq ι] {s : Finset ι} {i : ι} (h : i ∈ s) (f : ι → M) (b : M) : ∑ x ∈ s, Function.update f i b x = b + ∑ x ∈ s \\ {i}, f x",
      "module": "Mathlib.Algebra.BigOperators.Group.Finset.Piecewise"
    },
    {
      "name": "MultilinearMap.map_update_sum",
      "type": " {R : Type uR} {ι : Type uι} {M₁ : ι → Type v₁} {M₂ : Type v₂} [Semiring R] [(i : ι) → AddCommMonoid (M₁ i)] [AddCommMonoid M₂] [(i : ι) → Module R (M₁ i)] [Module R M₂] (f : MultilinearMap R M₁ M₂) {α : Type u_2} [DecidableEq ι] (t : Finset α) (i : ι) (g : α → M₁ i) (m : (i : ι) → M₁ i) : f (Function.update m i (∑ a ∈ t, g a)) = ∑ a ∈ t, f (Function.update m i (g a))",
      "module": "Mathlib.LinearAlgebra.Multilinear.Basic"
    },
    {
      "name": "MultilinearMap.linearDeriv_apply",
      "type": " {R : Type uR} {ι : Type uι} {M₁ : ι → Type v₁} {M₂ : Type v₂} [Semiring R] [(i : ι) → AddCommMonoid (M₁ i)] [AddCommMonoid M₂] [(i : ι) → Module R (M₁ i)] [Module R M₂] [DecidableEq ι] [Fintype ι] (f : MultilinearMap R M₁ M₂) (x y : (i : ι) → M₁ i) : (f.linearDeriv x) y = ∑ i, f (Function.update x i (y i))",
      "module": "Mathlib.LinearAlgebra.Multilinear.Basic"
    },
    {
      "name": "AlternatingMap.map_update_sum",
      "type": " {R : Type u_1} [Semiring R] {M : Type u_2} [AddCommMonoid M] [Module R M] {N : Type u_3} [AddCommMonoid N] [Module R N] {ι : Type u_7} (f : M [⋀^ι]→ₗ[R] N) {α : Type u_12} [DecidableEq ι] (t : Finset α) (i : ι) (g : α → M) (m : ι → M) : f (Function.update m i (∑ a ∈ t, g a)) = ∑ a ∈ t, f (Function.update m i (g a))",
      "module": "Mathlib.LinearAlgebra.Alternating.Basic"
    },
    {
      "name": "Matrix.detp_option_expand_row_none",
      "type": " {n : Type u_1} {R : Type u_3} [Fintype n] [DecidableEq n] [CommSemiring R] (s : ℤˣ) (A : Matrix (Option n) (Option n) R) : Matrix.detp s A = A none none * Matrix.detp s (A.submatrix some some) + ∑ k, A none (some k) * Matrix.detp (-s) (A.submatrix some (Function.update some k none))",
      "module": "Mathlib.LinearAlgebra.Matrix.SemiringInverse"
    },
    {
      "name": "ContinuousMultilinearMap.linearDeriv_apply",
      "type": " {R : Type u} {ι : Type v} {M₁ : ι → Type w₁} {M₂ : Type w₂} [Semiring R] [(i : ι) → AddCommMonoid (M₁ i)] [AddCommMonoid M₂] [(i : ι) → Module R (M₁ i)] [Module R M₂] [(i : ι) → TopologicalSpace (M₁ i)] [TopologicalSpace M₂] (f : ContinuousMultilinearMap R M₁ M₂) [ContinuousAdd M₂] [DecidableEq ι] [Fintype ι] (x y : (i : ι) → M₁ i) : (f.linearDeriv x) y = ∑ i, f (Function.update x i (y i))",
      "module": "Mathlib.Topology.Algebra.Module.Multilinear.Basic"
    },
    {
      "name": "ContinuousMultilinearMap.fderivCompContinuousLinearMap_apply",
      "type": " {𝕜 : Type u} {ι : Type v} {E : ι → Type wE} {E₁ : ι → Type wE₁} {G : Type wG} [NontriviallyNormedField 𝕜] [(i : ι) → SeminormedAddCommGroup (E i)] [(i : ι) → NormedSpace 𝕜 (E i)] [(i : ι) → SeminormedAddCommGroup (E₁ i)] [(i : ι) → NormedSpace 𝕜 (E₁ i)] [SeminormedAddCommGroup G] [NormedSpace 𝕜 G] [Fintype ι] [DecidableEq ι] (f : ContinuousMultilinearMap 𝕜 E₁ G) (g dg : (i : ι) → E i →L[𝕜] E₁ i) (v : (i : ι) → E i) : ((f.fderivCompContinuousLinearMap g) dg) v = ∑ i, f fun j => (Function.update g i (dg i) j) (v j)",
      "module": "Mathlib.Analysis.Normed.Module.Multilinear.Basic"
    }
